1	//! The checker a run asks, and the one place that picks which: the `tsrs` crates linked into this process, or a
2	//! `tsc --api` process when an explicit `tsc_path` names one (the Go `typescript@7.1` the tests and the parity gate
3	//! run, or a `tsrs` binary). Both answer the same methods with the same JSON, so [`crate::rpc`] does not know which.
4	//!
5	//! The linked checker answers on one thread of its own with a 512 MiB stack, the stack the `tsrs` binary serves on. A
6	//! query runs on the thread that calls it, and a type nested 2,000 deep overflows a default 2 MiB thread: a stack
7	//! overflow aborts the whole process and cannot be caught. Callers on any thread send it requests over a channel, and
8	//! it answers them one at a time, in the order they arrive. A panic inside the checker comes back as an error to the
9	//! request that caused it (`tsrs_api` catches it), and the session keeps answering.
10	
11	use std::sync::{Arc, mpsc};
12	use std::thread::JoinHandle;
13	use std::time::Duration;
14	
15	use caliper_docgen_tsc_client::{MalformedFrameReason, Supervisor, SupervisorConfig, TscClientError};
16	use camino::Utf8Path;
17	use serde_json::Value;
18	use serde_json::value::RawValue;
19	use tokio::sync::oneshot;
20	use tsrs_api::{Handler, Response, Session, SessionOptions};
21	use tsrs_vfs::{FS, bundled, osvfs};
22	
23	use crate::locate;
24	
25	/// The stack of the thread the linked checker answers on: what the `tsrs` binary gives each of its threads.
26	const CHECKER_STACK_BYTES: usize = 512 << 20;
27	
28	/// The JSON-RPC code the `tsrs` and `tsc` processes answer a failed request with (`jsonrpc.CodeInternalError`); the
29	/// message is the error's text, as here.
30	const INTERNAL_ERROR: i64 = -32603;
31	
32	/// How to start a checker: an explicit binary runs as a process, none links the bundled one.
33	pub(crate) struct Start<'a> {
34	    pub(crate) project_root: &'a Utf8Path,
35	    pub(crate) tsc_path: Option<&'a Utf8Path>,
36	    pub(crate) expected_versions: &'static [&'static str],
37	    pub(crate) timeout: Duration,
38	    pub(crate) extra_env: &'a [(String, String)],
39	}
40	
41	/// A running checker.
42	pub(crate) enum Backend {
43	    /// A `tsc --api` process for an explicit binary.
44	    Process(Box<Supervisor>),
45	    /// The checker linked into this process, on its own thread.
46	    InProcess(InProcess),
47	}
48	
49	impl Backend {
50	    /// The checker `start` asks for. An explicit path that does not exist, a binary that does not start or is not a
51	    /// supported version, or a checker thread that cannot be spawned, is an error that says so.
52	    pub(crate) async fn start(start: Start<'_>) -> Result<Backend, String> {
53	        let Some(tsc_path) = start.tsc_path else {
54	            return InProcess::start(start.project_root).map(Backend::InProcess);
55	        };
56	        let tsc_path = locate::explicit_tsc(tsc_path)?;
57	        let mut config = SupervisorConfig::new(tsc_path, start.project_root.to_owned(), start.expected_versions);
58	        config.handshake_timeout = start.timeout;
59	        config.extra_env = start.extra_env.to_vec();
60	        Supervisor::spawn(config)
61	            .await
62	            .map(|supervisor| Backend::Process(Box::new(supervisor)))
63	            .map_err(|error| error.to_string())
64	    }
65	
66	    pub(crate) fn client(&self) -> Client {
67	        match self {
68	            Backend::Process(supervisor) => Client::Process(supervisor.client()),
69	            Backend::InProcess(checker) => Client::InProcess(checker.client.clone()),
70	        }
71	    }
72	
73	    pub(crate) fn is_alive(&self) -> bool {
74	        match self {
75	            Backend::Process(supervisor) => supervisor.is_alive(),
76	            Backend::InProcess(checker) => !checker.thread.is_finished(),
77	        }
78	    }
79	
80	    /// The operating system's id of the checker process; `None` for the linked checker, which is this process.
81	    pub(crate) fn process_id(&self) -> Option<u32> {
82	        match self {
83	            Backend::Process(supervisor) => supervisor.process_id(),
84	            Backend::InProcess(_) => None,
85	        }
86	    }
87	
88	    /// Stops the checker. A process is reaped. The linked checker's thread finishes the request it is in, closes its
89	    /// session and exits on its own: it is not waited for, so a hung request cannot hold the caller.
90	    pub(crate) async fn shutdown(self) {
91	        match self {
92	            Backend::Process(supervisor) => {
93	                if let Err(error) = (*supervisor).shutdown().await {
94	                    tracing::debug!(%error, "the checker process did not shut down cleanly");
95	                }
96	            }
97	            Backend::InProcess(checker) => checker.client.stop(),
98	        }
99	    }
100	}
101	
102	/// A handle that sends requests to a running checker. Cheap to clone.
103	#[derive(Clone)]
104	pub(crate) enum Client {
105	    Process(caliper_docgen_tsc_client::Client),
106	    InProcess(Linked),
107	}
108	
109	impl Client {
110	    /// One request, its answer the `result` as the JSON text it arrived as. The wait is bounded by `deadline`; an
111	    /// error is the one the process route would give for the same failure.
112	    pub(crate) async fn request_raw(
113	        &self,
114	        method: &str,
115	        params: Value,
116	        deadline: Duration,
117	    ) -> Result<Box<RawValue>, TscClientError> {
118	        match self {
119	            Client::Process(client) => Ok(client.request_raw(method, params, deadline).await?.result),
120	            Client::InProcess(linked) => linked.request(method, params, deadline).await,
121	        }
122	    }
123	}
124	
125	/// The linked checker: the thread that owns its session, and the way to it.
126	pub(crate) struct InProcess {
127	    client: Linked,
128	    thread: JoinHandle<()>,
129	}
130	
131	enum Job {
132	    Request(Asked),
133	    /// Close the session and end the thread; requests sent after it fail as from a stopped checker.
134	    Stop,
135	}
136	
137	struct Asked {
138	    method: String,
139	    params: Vec<u8>,
140	    reply: oneshot::Sender<Result<String, String>>,
141	}
142	
143	/// The sending end of the linked checker's queue.
144	#[derive(Clone)]
145	pub(crate) struct Linked {
146	    jobs: mpsc::Sender<Job>,
147	}
148	
149	impl InProcess {
150	    /// Spawns the checker thread, which creates its session there: the session's work, from the first request on,
151	    /// runs on that thread's stack.
152	    pub(crate) fn start(project_root: &Utf8Path) -> Result<InProcess, String> {
153	        let (jobs, queue) = mpsc::channel();
154	        let cwd = project_root.to_string();
155	        let thread = std::thread::Builder::new()
156	            .name("caliper-checker".to_string())
157	            .stack_size(CHECKER_STACK_BYTES)
158	            .spawn(move || serve(cwd, queue))
159	            .map_err(|error| format!("could not start the checker thread: {error}"))?;
160	        Ok(InProcess { client: Linked { jobs }, thread })
161	    }
162	}
163	
164	impl Linked {
165	    async fn request(&self, method: &str, params: Value, deadline: Duration) -> Result<Box<RawValue>, TscClientError> {
166	        let params = serde_json::to_vec(&params).map_err(|error| TscClientError::Serialize(Arc::new(error)))?;
167	        let (reply, answer) = oneshot::channel();
168	        let asked = Asked { method: method.to_string(), params, reply };
169	        if self.jobs.send(Job::Request(asked)).is_err() {
170	            return Err(TscClientError::SessionClosed);
171	        }
172	        let answered = match tokio::time::timeout(deadline, answer).await {
173	            Ok(Ok(answered)) => answered,
174	            // The thread ended without answering: stopped, or its session could not be created.
175	            Ok(Err(_dropped)) => return Err(TscClientError::SessionClosed),
176	            Err(_elapsed) => return Err(TscClientError::Timeout { method: method.to_string(), after: deadline }),
177	        };
178	        match answered {
179	            Ok(text) => RawValue::from_string(text)
180	                .map_err(|_invalid| TscClientError::MalformedFrame { reason: MalformedFrameReason::InvalidJson }),
181	            Err(message) => Err(TscClientError::RpcError { code: INTERNAL_ERROR, message, data: None }),
182	        }
183	    }
184	
185	    fn stop(&self) {
186	        // A thread that already ended has nothing to stop.
187	        self.jobs.send(Job::Stop).ok();
188	    }
189	}
190	
191	/// The checker thread: one session, answering each request in turn until it is stopped or every sender is gone.
192	fn serve(cwd: String, queue: mpsc::Receiver<Job>) {
193	    let fs: Arc<dyn FS> = Arc::new(bundled::wrap_fs(osvfs::fs()));
194	    let session = Session::new(SessionOptions::new(cwd, bundled::lib_path(), fs, false));
195	    for job in queue {
196	        let asked = match job {
197	            Job::Request(asked) => asked,
198	            Job::Stop => break,
199	        };
200	        // A caller that stopped waiting (its deadline passed, its run ended) is not answered.
201	        if asked.reply.is_closed() {
202	            continue;
203	        }
204	        let answer = match session.handle_request(&asked.method, &asked.params) {
205	            Ok(Response::Json(text)) => Ok(text),
206	            Ok(Response::Binary(_)) => Err(format!("{} answered in binary, not JSON", asked.method)),
207	            Err(error) => Err(error.to_string()),
208	        };
209	        asked.reply.send(answer).ok();
210	    }
211	    session.close();
212	}
