253	            let found = match &keys {
254	                Some(keys) => {
255	                    let env = vec![("RAYON_NUM_THREADS".to_string(), count.clone())];
256	                    let v = run_variant(src, tsc, keys, run, env);
257	                    sampled = keys.len();
258	                    Some((v.hash, v.bytes, v.asked - v.structural.len(), format!("{:?}", v.structural), v.most_threads))
259	                }
260	                None => built_in_variant(src, components, count, run).map(|v| {
261	                    sampled = v["components"].as_u64().unwrap_or(0) as usize;
262	                    (
263	                        v["hash"].as_u64().unwrap_or(0),
264	                        v["bytes"].as_u64().unwrap_or(0) as usize,
265	                        v["answeredByChecker"].as_u64().unwrap_or(0) as usize,
266	                        v["structuralOnly"].to_string(),
267	                        v["maxProcessThreads"].as_u64().unwrap_or(0) as usize,
268	                    )
269	                }),
270	            };
271	            let Some((hash, bytes, answered, structural, most_threads)) = found else {
272	                ok = false;
273	                variants.push(format!("{{\"threads\":{count},\"run\":{run},\"applied\":false}}"));
274	                continue;
275	            };
276	            let same = *reference.get_or_insert(hash) == hash;
277	            // A component the checker declines keeps its structural answer; that is deterministic too, and is listed.
278	            ok &= same;
279	            variants.push(format!(
280	                "{{\"threads\":{count},\"run\":{run},\"reversed\":{reversed},\"bytes\":{bytes},\"answeredByChecker\":{answered},\"structuralOnly\":{structural},\"maxProcessThreads\":{most_threads},\"applied\":true,\"equalsFirst\":{same}}}"
281	            ));
282	        }
283	    }
284	    // Nothing sampled compares nothing.
285	    ok &= sampled > 0;
286	    println!("{{\"gate\":\"determinism\",\"components\":{sampled},\"variants\":[{}],\"ok\":{ok}}}", variants.join(","));
287	    ok
288	}
289	
290	fn percentile(sorted: &[f64], at: f64) -> f64 {
291	    let index = ((sorted.len() as f64 * at).ceil() as usize).clamp(1, sorted.len().max(1)) - 1;
292	    sorted.get(index).copied().unwrap_or(0.0)
293	}
294	
295	/// Each answer's JSON entry and diagnostics, in `keys` order.
296	fn answer_bytes(session: &WatchSession, keys: &[String]) -> Vec<String> {
297	    keys.iter()
298	        .map(|key| {
299	            let answer = session.component(key).expect("a sampled key is a component");
300	            format!("{key}\n{}\n{:?}", serde_json::to_string(&answer.entry).unwrap(), answer.diagnostics)
301	        })
302	        .collect()
303	}
304	
305	/// The options of [`watch`].
306	struct WatchRun {
307	    edits: usize,
308	    sample: usize,
309	    budget_ms: f64,
310	    max_rss_mib: Option<u64>,
311	    own_props: bool,
312	}
313	
314	/// ADR 0026 S6: edit-and-query on the kept snapshot. Rewrites one component's file (`ButtonProps & { edit{n}: string }`),
315	/// applies it with `update_file`, which tells the checker, and times that and the component's answer, `--edits` times,
316	/// sampling the checker's resident memory after each. Then it times the checker's answer alone on its unchanged
317	/// snapshot, and byte-compares the edited component and every `--sample`th other component with a fresh session asked
318	/// in reverse order. Passes when every answer is the checker's, carries its edit and no warning, memory stays under
319	/// `--max-rss-mib`, the bytes match, and the p95 is at most `--budget-ms`. `--props own` edits a component with one prop
320	/// of its own in the same program instead ([`own_props_source`]).
321	fn watch(src: &Utf8PathBuf, tsc: &str, run: WatchRun) -> bool {
322	    let WatchRun { edits, sample, budget_ms, max_rss_mib, own_props } = run;
323	    let source = if own_props { own_props_source } else { edit_source };
324	    let file = src.join("GateEdited.tsx");
325	    std::fs::write(&file, source(0)).unwrap();
326	    let (session, checker) = open(src, tsc, Vec::new(), max_rss_mib);
327	    let threshold = max_rss_mib.unwrap_or(OnDemandConfig::new(src.clone()).max_rss_mib);
328	    drop(session.component("GateEdited").expect("GateEdited is a component"));
329	    let (mut times, mut updates, mut processes, mut peak) = (Vec::new(), Vec::new(), BTreeSet::new(), 0);
330	    let (mut answered, mut stale, mut warned) = (0, 0, 0);
331	    // CPU time is what an edit costs whatever else the machine runs: the checker's, each process's last reading.
332	    let (own_cpu, first) = (cpu_ms(std::process::id()), checker.process_id());
333	    let first_cpu = first.and_then(cpu_ms).unwrap_or(0.0);
334	    let mut checker_cpu = std::collections::BTreeMap::new();
335	    for n in 1..=edits {
336	        std::fs::write(&file, source(n)).unwrap();
337	        let began = Instant::now();
338	        session.update_file(&file);
339	        updates.push(began.elapsed().as_secs_f64() * 1000.0);
340	        let answer = session.component("GateEdited").expect("GateEdited is a component");
341	        times.push(began.elapsed().as_secs_f64() * 1000.0);
342	        answered += usize::from(by_checker(&answer));
343	        stale += usize::from(!answer.entry.props.contains_key(&format!("edit{n}")));
344	        warned += usize::from(answer.diagnostics.iter().any(|d| d.severity == DiagnosticSeverity::Warning));
345	        if let Some(pid) = checker.process_id() {
346	            processes.insert(pid);
347	            peak = peak.max(process_stats(pid).map_or(0, |(mib, _)| mib));
348	            if let Some(ms) = cpu_ms(pid) {
349	                checker_cpu.insert(pid, ms);
350	            }
351	        }
352	    }
353	    let checker_cpu = (checker_cpu.values().sum::<f64>() - first_cpu) / edits as f64;
354	    let own_cpu = own_cpu.zip(cpu_ms(std::process::id())).map_or(0.0, |(start, end)| (end - start) / edits as f64);
355	    let snapshots = checker.snapshots();
356	
357	    // The checker's answer alone: the same request the session sends, on the snapshot it keeps, nothing changed.
358	    let entry = session.component("GateEdited").unwrap().entry;
359	    let target = SemanticTarget {
360	        key: "GateEdited".to_string(),
361	        file_path: entry.file_path.clone(),
362	        display_name: entry.display_name.clone(),
363	        exports: entry.exports.clone(),
364	        described: entry.props.values().filter(|p| !p.description.is_empty()).map(|p| p.name.clone()).collect(),
365	        react_wanted: react_props_wanted(session.options.html_attributes, &entry.props),
366	    };
367	    let mut query = Vec::new();
368	    for _ in 0..21 {
369	        let began = Instant::now();
370	        drop(checker.request(vec![target.clone()]).recv_timeout(Duration::from_secs(120)));
371	        query.push(began.elapsed().as_secs_f64() * 1000.0);
372	    }
373	
374	    let mut keys = session.component_keys();
375	    keys.retain(|key| key != "GateEdited");
376	    keys.sort();
377	    let mut keys: Vec<String> = keys.into_iter().step_by(sample.max(1)).collect();
378	    keys.insert(0, "GateEdited".to_string());
379	    let watched = answer_bytes(&session, &keys);
380	    let (fresh_session, _fresh) = open(src, tsc, Vec::new(), None);
381	    let reversed: Vec<String> = keys.iter().rev().cloned().collect();
382	    let mut fresh = answer_bytes(&fresh_session, &reversed);
383	    fresh.reverse();
384	    let identical = watched == fresh;
385	    let recycles = checker.recycles();
386	
387	    times.sort_by(f64::total_cmp);
388	    updates.sort_by(f64::total_cmp);
389	    query.sort_by(f64::total_cmp);
390	    let (p50, p95, p99) = (percentile(&times, 0.5), percentile(&times, 0.95), percentile(&times, 0.99));
391	    let ok = answered == edits && stale == 0 && warned == 0 && identical && peak <= threshold && p95 <= budget_ms;
392	    println!(
393	        "{{\"gate\":\"watch\",\"props\":\"{}\",\"edits\":{edits},\"answeredByChecker\":{answered},\"staleAnswers\":{stale},\"warnedAnswers\":{warned},\"snapshots\":{{\"created\":{},\"updated\":{}}},\"processes\":{},\"recycles\":{{\"worn\":{},\"bloated\":{}}},\"peakRssMib\":{peak},\"maxRssMib\":{threshold},\"editAndQueryMs\":{{\"p50\":{p50:.1},\"p95\":{p95:.1},\"p99\":{p99:.1},\"max\":{:.1}}},\"updateFileMs\":{{\"p50\":{:.1}}},\"cpuMsPerEdit\":{{\"checker\":{checker_cpu:.1},\"caliper\":{own_cpu:.1}}},\"queryOnlyMs\":{{\"p50\":{:.1},\"min\":{:.1}}},\"budgetMs\":{budget_ms},\"comparedComponents\":{},\"comparedBytes\":{},\"equalsFreshReversed\":{identical},\"ok\":{ok}}}",
394	        if own_props { "own" } else { "button" },
395	        snapshots.created,
396	        snapshots.updated,
397	        processes.len(),
398	        recycles.worn,
399	        recycles.bloated,
400	        times.last().copied().unwrap_or(0.0),
401	        percentile(&updates, 0.5),
402	        percentile(&query, 0.5),
403	        query.first().copied().unwrap_or(0.0),
404	        keys.len(),
405	        watched.iter().map(String::len).sum::<usize>(),
406	    );
407	    ok
408	}
409	
410	/// ADR 0026 S4: how long a story waits for the checker's answer through the Rust client. Each run opens a fresh session
411	/// as the addon does (the checker started in the background at creation), waits until that process is up, then asks for
412	/// `key` once and times the whole answer: the structural pass and the checker's program and conversion for the
413	/// component. Passes when every answer is the checker's and the median is at most `budget_ms`, the addon's default
414	/// `semanticWaitMs`.
415	fn first_answer(src: &Utf8PathBuf, tsc: &str, key: &str, runs: usize, budget_ms: u128) -> bool {
416	    let (mut start, mut first, mut structural, mut answered) = (Vec::new(), Vec::new(), Vec::new(), 0);
417	    for _ in 0..runs.max(1) {
418	        let plain = WatchSession::lazy(PipelineOptions {
419	            src_dirs: vec![src.clone()],
420	            load_dependencies: true,
421	            collapse_inherited_props: CollapseInheritedProps::None,
422	            ..PipelineOptions::default()
423	        });
424	        drop(plain.initialize());
425	        let began = Instant::now();
426	        drop(plain.component(key).expect("the key is a component"));
427	        structural.push(began.elapsed().as_millis());
428	
429	        let (session, checker) = open(src, tsc, Vec::new(), None);
430	        let began = Instant::now();
431	        checker.warm_up();
432	        // Queued behind the warm-up, an empty request returns once the process is up and initialized.
433	        drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
434	        start.push(began.elapsed().as_millis());
435	        let began = Instant::now();
436	        let answer = session.component(key).expect("the key is a component");
437	        first.push(began.elapsed().as_millis());
438	        answered += usize::from(by_checker(&answer));
439	    }
440	    let median = |values: &mut Vec<u128>| {
441	        values.sort_unstable();
442	        values[values.len() / 2]
443	    };
444	    let (start_ms, first_ms, structural_ms) = (median(&mut start), median(&mut first), median(&mut structural));
445	    let ok = answered == first.len() && first_ms <= budget_ms;
446	    println!(
447	        "{{\"gate\":\"first-answer\",\"component\":{key:?},\"runs\":{},\"answeredByChecker\":{answered},\"startMs\":{start_ms},\"structuralMs\":{structural_ms},\"firstAnswerMs\":{first_ms},\"firstAnswerEachMs\":{first:?},\"budgetMs\":{budget_ms},\"ok\":{ok}}}",
448	        first.len(),
449	    );
450	    ok
451	}
452	
453	fn main() {
454	    let args: Vec<String> = std::env::args().collect();
455	    let src = Utf8PathBuf::from(arg(&args, "--src").expect("--src"));
456	    let src = Utf8PathBuf::from_path_buf(std::fs::canonicalize(src).unwrap()).unwrap();
457	    let tsc = arg(&args, "--tsc").expect("--tsc");
458	    let number = |name: &str, default: usize| arg(&args, name).map_or(default, |n| n.parse().expect("a number"));
459	    let ok = match args.get(1).map(String::as_str) {
460	        Some("memory") => memory(
461	            &src,
462	            &tsc,
463	            number("--edits", 650),
464	            arg(&args, "--max-rss-mib").map(|n| n.parse().expect("a number")),
465	        ),
466	        Some("determinism") => {
467	            let threads = arg(&args, "--threads").unwrap_or_else(|| "1,2,4".to_string());
468	            determinism(
469	                &src,
470	                &tsc,
471	                number("--components", 150),
472	                &threads.split(',').map(str::to_string).collect::<Vec<_>>(),
473	                number("--runs", 3),
474	            )
475	        }
476	        Some("determinism-variant") => determinism_variant(
477	            &src,
478	            number("--components", 150),
479	            &arg(&args, "--threads").expect("--threads"),
480	            number("--run", 0),
481	        ),
482	        Some("watch") => watch(
483	            &src,
484	            &tsc,
485	            WatchRun {
486	                edits: number("--edits", 300),
487	                sample: number("--sample", 100),
488	                budget_ms: arg(&args, "--budget-ms").map_or(25.0, |n| n.parse().expect("a number")),
489	                max_rss_mib: arg(&args, "--max-rss-mib").map(|n| n.parse().expect("a number")),
490	                own_props: arg(&args, "--props").is_some_and(|props| props == "own"),
491	            },
492	        ),
493	        Some("first-answer") => first_answer(
494	            &src,
495	            &tsc,
496	            &arg(&args, "--component").unwrap_or_else(|| "ChakraButton".to_string()),
497	            number("--runs", 5),
498	            arg(&args, "--budget-ms").map_or(150, |n| n.parse().expect("a number")),
499	        ),
500	        _ => {
501	            eprintln!("usage: gate_harness memory|determinism|first-answer|watch --src DIR --tsc PATH");
502	            false
503	        }
504	    };
505	    std::process::exit(i32::from(!ok));
506	}
