1	//! A warm checker that answers for the components a session asks about, one request at a time.
2	//!
3	//! The one-shot [`crate::resolve`] roots a single program at every component's file. A Storybook session asks about
4	//! one component per story, so this keeps one checker warm (the built-in one, or a `tsc --api` process for an explicit
5	//! `tsc_path`), starts it on the first request, and roots a small program at just the requested files: the checker
6	//! loads what those files import, not the project.
7	//!
8	//! The snapshot of that program is kept between requests (ADR 0026 S6). The next request brings it up to date with
9	//! `updateSnapshot`, which re-reads only the files the session announced as changed ([`SemanticProvider::changed`]) and
10	//! keeps the rest as parsed, re-rooting the program when the request names other files. The checker does not see an
11	//! edit it is not told about, so before an answer every file the program read is compared with the stamp it had when
12	//! read ([`crate::stamps`]): one that changed unannounced makes the answer come from a fresh snapshot, with a warning
13	//! that names it.
14	//!
15	//! The worker runs on its own thread with its own runtime, so a caller on any thread (a NAPI worker, a rayon task)
16	//! never nests runtimes and can bound how long it waits. A failure to start or a crash yields an outcome with no
17	//! components and one diagnostic, never an error; after [`MAX_RESTARTS`] crashes the checker stays down.
18	//!
19	//! A checker is replaced after [`MAX_REQUESTS_PER_PROCESS`] programs, and a checker process also when its resident
20	//! memory passes [`OnDemandConfig::max_rss_mib`]. The built-in checker is replaced by a fresh session on the same
21	//! program count, which drops what the old one held. Its memory is this process's, which the allocator keeps for reuse
22	//! rather than returning, and which a host such as Storybook also counts, so the memory bound is not applied to it.
23	//!
24	//! Requests wait in two queues: an interactive one (a story someone opened) is answered before any background one (a
25	//! warm-up, a fill, a prefetch), first come first served within each, and a background request a caller raised while
26	//! it waited moves to the interactive queue. So that background work is never starved, after [`INTERACTIVE_STREAK`]
27	//! interactive answers in a row while background requests wait, the oldest of them goes next.
28	
29	use std::collections::{BTreeSet, VecDeque};
30	use std::sync::atomic::{AtomicU32, Ordering};
31	use std::sync::{Arc, mpsc};
32	use std::thread::JoinHandle;
33	use std::time::{Duration, SystemTime};
34	
35	use caliper_docgen_core::types::semantic::{
36	    Delivery, Priority, SemanticOutcome, SemanticProvider, SemanticTarget, SharedPriority, SourceChange,
37	};
38	use caliper_docgen_core::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
39	use camino::Utf8PathBuf;
40	use rustc_hash::{FxHashMap, FxHashSet};
41	use tokio::sync::mpsc::error::TryRecvError;
42	use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender, unbounded_channel};
43	
44	use crate::checker::{Backend, Client};
45	use crate::rpc::{CallError, Rpc};
46	use crate::stamps::{self, Stamp};
47	use crate::{SUPPORTED_VERSIONS, SemanticRequest, answer_on, group_by_file, root_files, start_checker};
48	
49	/// How many files an unannounced-edit warning names before it counts the rest.
50	const UNTOLD_NAMED: usize = 5;
51	
52	/// Interactive answers in a row the checker gives while background requests wait, before the oldest background request
53	/// goes next: once first in its queue, a background request waits behind at most this many interactive ones.
54	const INTERACTIVE_STREAK: u32 = 4;
55	
56	/// Crashes the checker may have before it stays down for the session.
57	const MAX_RESTARTS: u32 = 3;
58	
59	/// Programs one checker builds before it is replaced. Its memory grows with every program it has loaded (measured:
60	/// antd reached 600 MiB after 50 single-component programs), and a fresh process costs 30 to 70 ms.
61	const MAX_REQUESTS_PER_PROCESS: u32 = 64;
62	
63	/// Resident memory, in MiB, past which a `tsc` process is replaced between requests. Measured single-component programs
64	/// peak at 157 to 612 MiB (antd the highest); a process past this has loaded more than a story session needs.
65	const DEFAULT_MAX_RSS_MIB: u64 = 768;
66	
67	/// How many requests pass between memory checks: each reads the process table, which costs a few milliseconds.
68	const RSS_CHECK_EVERY: u32 = 4;
69	
70	/// How long dropping a checker waits, by default, for its worker to finish a request and stop `tsc`, before leaving the
71	/// worker to finish on its own. Closing a session must not wait for a 60 s request.
72	const DEFAULT_SHUTDOWN_WAIT: Duration = Duration::from_secs(5);
73	
74	/// How a warm [`OnDemand`] checker starts and is kept: which checker, how long to wait on it, and when to replace it.
75	#[derive(Debug, Clone)]
76	pub struct OnDemandConfig {
77	    /// Where the checker finds `node_modules`: its working directory.
78	    pub project_root: Utf8PathBuf,
79	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
80	    pub tsconfig: Option<Utf8PathBuf>,
81	    /// A checker binary to run as a `tsc --api` process (`typescript@7.1`'s `tsc`, or `tsrs`) instead of the built-in
82	    /// checker.
83	    pub tsc_path: Option<Utf8PathBuf>,
84	    /// Bound on each request to the checker, and on a checker process's start-up handshake.
85	    pub request_timeout: Duration,
86	    /// The versions a checker binary's `package.json` may declare; one that is not among them is a start-up failure.
87	    /// The built-in checker is pinned and not checked.
88	    pub expected_versions: &'static [&'static str],
89	    /// Resident memory of a checker process, in MiB, past which it is replaced after a request. A request that needs
90	    /// more finishes first: the bound is between requests, not inside one. The built-in checker is not bound by it.
91	    pub max_rss_mib: u64,
92	    /// How long dropping the checker waits for a request in progress before it lets the worker finish alone.
93	    pub shutdown_wait: Duration,
94	    /// Environment for a checker process; the tests use it to pick a replay scenario.
95	    pub extra_env: Vec<(String, String)>,
96	}
97	
98	impl OnDemandConfig {
99	    /// A configuration for `project_root` with a 60 second request timeout, the supported versions, a 768 MiB memory
100	    /// bound, a 5 second shutdown wait, and no explicit tsconfig or `tsc` path.
101	    pub fn new(project_root: Utf8PathBuf) -> Self {
102	        Self {
103	            project_root,
104	            tsconfig: None,
105	            tsc_path: None,
106	            request_timeout: Duration::from_secs(60),
107	            expected_versions: SUPPORTED_VERSIONS,
108	            max_rss_mib: DEFAULT_MAX_RSS_MIB,
109	            shutdown_wait: DEFAULT_SHUTDOWN_WAIT,
110	            extra_env: Vec::new(),
111	        }
112	    }
113	}
114	
115	/// The resident memory of a process in MiB: `/proc` where it exists, else `ps`. `None` when neither answers.
116	fn resident_mib(pid: u32) -> Option<u64> {
117	    let kib = match std::fs::read_to_string(format!("/proc/{pid}/status")) {
118	        Ok(status) => status
119	            .lines()
120	            .find_map(|line| line.strip_prefix("VmRSS:"))?
121	            .split_whitespace()
122	            .next()?
123	            .parse::<u64>()
124	            .ok()?,
125	        Err(_) => {
126	            let output = std::process::Command::new("ps").args(["-o", "rss=", "-p", &pid.to_string()]).output().ok()?;
127	            String::from_utf8_lossy(&output.stdout).trim().parse::<u64>().ok()?
128	        }
129	    };
130	    Some(kib / 1024)
131	}
132	
133	/// How often a warm checker was replaced on purpose, by cause (crashes are not counted).
134	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
135	pub struct Recycles {
136	    /// Replaced after building the most programs one checker is allowed.
137	    pub worn: u32,
138	    /// Replaced after its resident memory passed [`OnDemandConfig::max_rss_mib`].
139	    pub bloated: u32,
140	}
141	
142	/// How the snapshots a warm checker answered from were made.
143	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
144	pub struct Snapshots {
145	    /// Built from the disk with `createSnapshot`: the first request of a process, one after a file changed that the
146	    /// checker was not told about, or one after a snapshot could not be listed or updated.
147	    pub created: u32,
148	    /// Brought up to date from the one before with `updateSnapshot`: announced edits re-read, the rest kept.
149	    pub updated: u32,
150	}
