152	/// What the worker thread reports about the process, for the type that owns the thread to read.
153	#[derive(Default)]
154	struct Gauges {
155	    worn: AtomicU32,
156	    bloated: AtomicU32,
157	    created: AtomicU32,
158	    updated: AtomicU32,
159	    /// The process that answered last; 0 before the first answer.
160	    process: AtomicU32,
