327	impl Drop for OnDemand {
328	    fn drop(&mut self) {
329	        // Closing the queue ends the worker loop, which stops the checker before the thread exits. A worker still inside
330	        // a long request is left to finish it: the checker stops when it does, or with this process.
331	        self.jobs.take();
332	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
333	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
334	        if let Some(thread) = self.thread.take()
335	            && stopped
336	        {
337	            thread.join().ok();
338	        }
339	    }
340	}
341	
342	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>, gauges: Arc<Gauges>) {
343	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
344	        Ok(runtime) => runtime,
345	        Err(error) => {
346	            let reason = format!("could not start an async runtime: {error}");
347	            while let Some(job) = queue.blocking_recv() {
348	                match job {
349	                    Job::Answer(asked) => asked.delivery.deliver(Some(SemanticOutcome::unavailable(reason.clone()))),
350	                    Job::Warm | Job::Changed(_) => {}
351	                }
352	            }
353	            return;
354	        }
355	    };
356	    runtime.block_on(async move {
357	        let mut checker = Checker { gauges, ..Checker::default() };
358	        let mut waiting = Queue::default();
359	        let mut open = true;
360	        loop {
361	            // Every job sent so far is taken before the next request is picked, so the queues hold every request that
362	            // waits, and a change is applied before any request sent after it.
363	            if waiting.is_empty() && open {
364	                match queue.recv().await {
365	                    Some(job) => checker.take(&config, job, &mut waiting).await,
366	                    None => open = false,
367	                }
368	            }
369	            while open {
370	                match queue.try_recv() {
371	                    Ok(job) => checker.take(&config, job, &mut waiting).await,
372	                    Err(TryRecvError::Empty) => break,
373	                    Err(TryRecvError::Disconnected) => open = false,
374	                }
375	            }
376	            let Some(asked) = waiting.next() else {
377	                match open {
378	                    true => continue,
379	                    false => break,
380	                }
381	            };
382	            asked.delivery.deliver(Some(checker.answer(&config, asked.targets).await));
383	            // After the reply, so the caller never waits for the memory check or the replacement.
384	            checker.maintain(&config).await;
385	        }
386	        if let Some(backend) = checker.backend.take() {
387	            backend.shutdown().await;
388	        }
389	    });
390	}
