314	/// ADR 0026 S6: edit-and-query on the kept snapshot. Rewrites one component's file (`ButtonProps & { edit{n}: string }`),
315	/// applies it with `update_file`, which tells the checker, and times that and the component's answer, `--edits` times,
316	/// sampling the checker's resident memory after each. Then it times the checker's answer alone on its unchanged
317	/// snapshot, and byte-compares the edited component and every `--sample`th other component with a fresh session asked
318	/// in reverse order. Passes when every answer is the checker's, carries its edit and no warning, memory stays under
319	/// `--max-rss-mib`, the bytes match, and the p95 is at most `--budget-ms`. `--props own` edits a component with one prop
320	/// of its own in the same program instead ([`own_props_source`]).
321	fn watch(src: &Utf8PathBuf, tsc: &str, run: WatchRun) -> bool {
322	    let WatchRun { edits, sample, budget_ms, max_rss_mib, own_props } = run;
323	    let source = if own_props { own_props_source } else { edit_source };
324	    let file = src.join("GateEdited.tsx");
325	    std::fs::write(&file, source(0)).unwrap();
326	    let (session, checker) = open(src, tsc, Vec::new(), max_rss_mib);
327	    let threshold = max_rss_mib.unwrap_or(OnDemandConfig::new(src.clone()).max_rss_mib);
328	    drop(session.component("GateEdited").expect("GateEdited is a component"));
329	    let (mut times, mut updates, mut processes, mut peak) = (Vec::new(), Vec::new(), BTreeSet::new(), 0);
330	    let (mut answered, mut stale, mut warned) = (0, 0, 0);
331	    // CPU time is what an edit costs whatever else the machine runs: the checker's, each process's last reading.
332	    let (own_cpu, first) = (cpu_ms(std::process::id()), checker.process_id());
333	    let first_cpu = first.and_then(cpu_ms).unwrap_or(0.0);
334	    let mut checker_cpu = std::collections::BTreeMap::new();
335	    for n in 1..=edits {
336	        std::fs::write(&file, source(n)).unwrap();
337	        let began = Instant::now();
338	        session.update_file(&file);
339	        updates.push(began.elapsed().as_secs_f64() * 1000.0);
340	        let answer = session.component("GateEdited").expect("GateEdited is a component");
341	        times.push(began.elapsed().as_secs_f64() * 1000.0);
342	        answered += usize::from(by_checker(&answer));
343	        stale += usize::from(!answer.entry.props.contains_key(&format!("edit{n}")));
344	        warned += usize::from(answer.diagnostics.iter().any(|d| d.severity == DiagnosticSeverity::Warning));
345	        if let Some(pid) = checker.process_id() {
346	            processes.insert(pid);
347	            peak = peak.max(process_stats(pid).map_or(0, |(mib, _)| mib));
348	            if let Some(ms) = cpu_ms(pid) {
349	                checker_cpu.insert(pid, ms);
350	            }
351	        }
352	    }
353	    let checker_cpu = (checker_cpu.values().sum::<f64>() - first_cpu) / edits as f64;
354	    let own_cpu = own_cpu.zip(cpu_ms(std::process::id())).map_or(0.0, |(start, end)| (end - start) / edits as f64);
355	    let snapshots = checker.snapshots();
356	
357	    // The checker's answer alone: the same request the session sends, on the snapshot it keeps, nothing changed.
358	    let entry = session.component("GateEdited").unwrap().entry;
359	    let target = SemanticTarget {
360	        key: "GateEdited".to_string(),
361	        file_path: entry.file_path.clone(),
362	        display_name: entry.display_name.clone(),
363	        exports: entry.exports.clone(),
364	        described: entry.props.values().filter(|p| !p.description.is_empty()).map(|p| p.name.clone()).collect(),
365	        react_wanted: react_props_wanted(session.options.html_attributes, &entry.props),
366	    };
367	    let mut query = Vec::new();
368	    for _ in 0..21 {
369	        let began = Instant::now();
370	        drop(checker.request(vec![target.clone()]).recv_timeout(Duration::from_secs(120)));
371	        query.push(began.elapsed().as_secs_f64() * 1000.0);
372	    }
373	
374	    let mut keys = session.component_keys();
375	    keys.retain(|key| key != "GateEdited");
376	    keys.sort();
377	    let mut keys: Vec<String> = keys.into_iter().step_by(sample.max(1)).collect();
378	    keys.insert(0, "GateEdited".to_string());
379	    let watched = answer_bytes(&session, &keys);
380	    let (fresh_session, _fresh) = open(src, tsc, Vec::new(), None);
381	    let reversed: Vec<String> = keys.iter().rev().cloned().collect();
382	    let mut fresh = answer_bytes(&fresh_session, &reversed);
383	    fresh.reverse();
384	    let identical = watched == fresh;
385	    let recycles = checker.recycles();
386	
387	    times.sort_by(f64::total_cmp);
388	    updates.sort_by(f64::total_cmp);
389	    query.sort_by(f64::total_cmp);
390	    let (p50, p95, p99) = (percentile(&times, 0.5), percentile(&times, 0.95), percentile(&times, 0.99));
391	    let ok = answered == edits && stale == 0 && warned == 0 && identical && peak <= threshold && p95 <= budget_ms;
392	    println!(
393	        "{{\"gate\":\"watch\",\"props\":\"{}\",\"edits\":{edits},\"answeredByChecker\":{answered},\"staleAnswers\":{stale},\"warnedAnswers\":{warned},\"snapshots\":{{\"created\":{},\"updated\":{}}},\"processes\":{},\"recycles\":{{\"worn\":{},\"bloated\":{}}},\"peakRssMib\":{peak},\"maxRssMib\":{threshold},\"editAndQueryMs\":{{\"p50\":{p50:.1},\"p95\":{p95:.1},\"p99\":{p99:.1},\"max\":{:.1}}},\"updateFileMs\":{{\"p50\":{:.1}}},\"cpuMsPerEdit\":{{\"checker\":{checker_cpu:.1},\"caliper\":{own_cpu:.1}}},\"queryOnlyMs\":{{\"p50\":{:.1},\"min\":{:.1}}},\"budgetMs\":{budget_ms},\"comparedComponents\":{},\"comparedBytes\":{},\"equalsFreshReversed\":{identical},\"ok\":{ok}}}",
394	        if own_props { "own" } else { "button" },
395	        snapshots.created,
396	        snapshots.updated,
397	        processes.len(),
398	        recycles.worn,
399	        recycles.bloated,
400	        times.last().copied().unwrap_or(0.0),
401	        percentile(&updates, 0.5),
402	        percentile(&query, 0.5),
403	        query.first().copied().unwrap_or(0.0),
404	        keys.len(),
405	        watched.iter().map(String::len).sum::<usize>(),
406	    );
407	    ok
408	}
