410	/// ADR 0026 S4: how long a story waits for the checker's answer through the Rust client. Each run opens a fresh session
411	/// as the addon does (the checker started in the background at creation), waits until that process is up, then asks for
412	/// `key` once and times the whole answer: the structural pass and the checker's program and conversion for the
413	/// component. Passes when every answer is the checker's and the median is at most `budget_ms`, the addon's default
414	/// `semanticWaitMs`.
415	fn first_answer(src: &Utf8PathBuf, tsc: &str, key: &str, runs: usize, budget_ms: u128) -> bool {
416	    let (mut start, mut first, mut structural, mut answered) = (Vec::new(), Vec::new(), Vec::new(), 0);
417	    for _ in 0..runs.max(1) {
418	        let plain = WatchSession::lazy(PipelineOptions {
419	            src_dirs: vec![src.clone()],
420	            load_dependencies: true,
421	            collapse_inherited_props: CollapseInheritedProps::None,
422	            ..PipelineOptions::default()
423	        });
424	        drop(plain.initialize());
425	        let began = Instant::now();
426	        drop(plain.component(key).expect("the key is a component"));
427	        structural.push(began.elapsed().as_millis());
428	
429	        let (session, checker) = open(src, tsc, Vec::new(), None);
430	        let began = Instant::now();
431	        checker.warm_up();
432	        // Queued behind the warm-up, an empty request returns once the process is up and initialized.
433	        drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
434	        start.push(began.elapsed().as_millis());
435	        let began = Instant::now();
436	        let answer = session.component(key).expect("the key is a component");
437	        first.push(began.elapsed().as_millis());
438	        answered += usize::from(by_checker(&answer));
439	    }
440	    let median = |values: &mut Vec<u128>| {
441	        values.sort_unstable();
442	        values[values.len() / 2]
443	    };
444	    let (start_ms, first_ms, structural_ms) = (median(&mut start), median(&mut first), median(&mut structural));
445	    let ok = answered == first.len() && first_ms <= budget_ms;
446	    println!(
447	        "{{\"gate\":\"first-answer\",\"component\":{key:?},\"runs\":{},\"answeredByChecker\":{answered},\"startMs\":{start_ms},\"structuralMs\":{structural_ms},\"firstAnswerMs\":{first_ms},\"firstAnswerEachMs\":{first:?},\"budgetMs\":{budget_ms},\"ok\":{ok}}}",
448	        first.len(),
449	    );
450	    ok
451	}
452	
