454	    let args: Vec<String> = std::env::args().collect();
455	    let src = Utf8PathBuf::from(arg(&args, "--src").expect("--src"));
456	    let src = Utf8PathBuf::from_path_buf(std::fs::canonicalize(src).unwrap()).unwrap();
457	    let tsc = arg(&args, "--tsc").expect("--tsc");
458	    let number = |name: &str, default: usize| arg(&args, name).map_or(default, |n| n.parse().expect("a number"));
459	    let ok = match args.get(1).map(String::as_str) {
460	        Some("memory") => memory(
461	            &src,
462	            &tsc,
463	            number("--edits", 650),
464	            arg(&args, "--max-rss-mib").map(|n| n.parse().expect("a number")),
465	        ),
466	        Some("determinism") => {
467	            let threads = arg(&args, "--threads").unwrap_or_else(|| "1,2,4".to_string());
468	            determinism(
469	                &src,
470	                &tsc,
471	                number("--components", 150),
472	                &threads.split(',').map(str::to_string).collect::<Vec<_>>(),
473	                number("--runs", 3),
474	            )
475	        }
476	        Some("determinism-variant") => determinism_variant(
477	            &src,
478	            number("--components", 150),
479	            &arg(&args, "--threads").expect("--threads"),
480	            number("--run", 0),
481	        ),
482	        Some("watch") => watch(
483	            &src,
484	            &tsc,
485	            WatchRun {
486	                edits: number("--edits", 300),
487	                sample: number("--sample", 100),
488	                budget_ms: arg(&args, "--budget-ms").map_or(25.0, |n| n.parse().expect("a number")),
489	                max_rss_mib: arg(&args, "--max-rss-mib").map(|n| n.parse().expect("a number")),
490	                own_props: arg(&args, "--props").is_some_and(|props| props == "own"),
