498	            arg(&args, "--budget-ms").map_or(150, |n| n.parse().expect("a number")),
499	        ),
500	        _ => {
501	            eprintln!("usage: gate_harness memory|determinism|first-answer|watch --src DIR --tsc PATH");
502	            false
503	        }
504	    };
505	    std::process::exit(i32::from(!ok));
