178	/// The requests waiting for the checker, in two queues by priority, first in first out within each. A request is
179	/// filed by its priority when it arrives and moved to the interactive queue when a caller raised it while it waited.
180	/// After [`INTERACTIVE_STREAK`] interactive requests in a row while the background queue is not empty, the next is
181	/// the oldest background request.
182	struct Queue<T> {
183	    interactive: VecDeque<(T, SharedPriority)>,
184	    background: VecDeque<(T, SharedPriority)>,
185	    /// Interactive requests taken in a row while a background one waited.
186	    streak: u32,
187	}
188	
189	impl<T> Default for Queue<T> {
190	    fn default() -> Self {
191	        Self { interactive: VecDeque::new(), background: VecDeque::new(), streak: 0 }
192	    }
193	}
194	
195	impl<T> Queue<T> {
196	    fn push(&mut self, item: T, priority: SharedPriority) {
197	        match priority.get() {
198	            Priority::Interactive => self.interactive.push_back((item, priority)),
199	            Priority::Background => self.background.push_back((item, priority)),
200	        }
201	    }
202	
203	    fn is_empty(&self) -> bool {
204	        self.interactive.is_empty() && self.background.is_empty()
205	    }
206	
207	    /// The request the checker answers next.
208	    fn next(&mut self) -> Option<T> {
209	        let (raised, waiting): (VecDeque<_>, VecDeque<_>) = std::mem::take(&mut self.background)
210	            .into_iter()
211	            .partition(|(_, priority)| priority.get() == Priority::Interactive);
212	        self.interactive.extend(raised);
213	        self.background = waiting;
214	        let starving = self.streak >= INTERACTIVE_STREAK;
215	        let (next, streak) = match (self.interactive.pop_front(), self.background.is_empty()) {
216	            (Some(interactive), true) => (Some(interactive), 0),
217	            (Some(interactive), false) if !starving => (Some(interactive), self.streak + 1),
218	            (Some(interactive), false) => {
219	                self.interactive.push_front(interactive);
220	                (self.background.pop_front(), 0)
221	            }
222	            (None, _) => (self.background.pop_front(), 0),
223	        };
224	        self.streak = streak;
225	        next.map(|(item, _)| item)
226	    }
227	}
