    fn handle_request(&self, method: &str, params: &[u8]) -> ApiResult<Response> {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            self.dispatch(method, params)
        })) {
            Ok(result) => result,
            Err(panic) => {
                let message = panic
