                Err(ApiError::internal(format!("panic: {message}")))
            }
        }
    }

    fn handle_notification(&self, _method: &str, _params: &[u8]) -> ApiResult<()> {
        // Go `Session.HandleNotification` ignores all notifications.
        Ok(())
    }
