pub(crate) unsafe fn discard(p: *mut u8, len: usize) {
    let page = page_size();
    let start = p.addr().next_multiple_of(page);
    let end = (p.addr() + len) & !(page - 1);
    if end <= start {
        return;
    }
    let q = p.with_addr(start);
    #[cfg(target_os = "linux")]
