// Scratch: throughput of checker.rs's `nesting` over the given files (the Chakra program's declarations).
fn nesting(text: &str) -> usize {
    let (mut brackets, mut angles, mut deepest) = (0usize, 0usize, 0usize);
    for byte in text.bytes() {
        match byte {
            b'(' | b'[' | b'{' => {
                brackets += 1;
                deepest = deepest.max(brackets);
            }
            b')' | b']' | b'}' => brackets = brackets.saturating_sub(1),
            b'<' => {
                angles += 1;
                deepest = deepest.max(angles);
            }
            b'>' => angles = angles.saturating_sub(1),
            _ => {}
        }
    }
    deepest
}

fn main() {
    let texts: Vec<String> = std::env::args().skip(1).filter_map(|p| std::fs::read_to_string(p).ok()).collect();
    let bytes: usize = texts.iter().map(String::len).sum();
    let mut best = f64::MAX;
    let mut deepest = 0;
    for _ in 0..20 {
        let t = std::time::Instant::now();
        deepest = texts.iter().map(|t| nesting(t)).max().unwrap_or(0);
        best = best.min(t.elapsed().as_secs_f64() * 1000.0);
    }
    println!("files {} bytes {} deepest {} best {:.2} ms", texts.len(), bytes, deepest, best);
}

